INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('21155c2e-9016-4ab3-af42-0bdcce94774b', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$101. óra: Feladatmegoldás$q$, $q$Összetett kerületszámítási és kerítésszámítási szöveges feladatok.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "4c593078-2d66-4f13-a3c0-2790f621bcaa", "text": "Egy téglalap alakú kert hossza 20 m, szélessége 15 m. Hány méter kerítés övezi a kertet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "70"}, {"id": "5a765dd4-4254-4cf8-949e-e3388e30ccc2", "text": "Hány méter kerítés kell a 20m x 15m-es kerthez, ha hagyunk egy 2 m-es kaput? (70 - 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "68"}, {"id": "4baed6d9-cb23-4f29-99ed-6ddcbab646ca", "text": "Egy négyzet alakú pálya kerülete 100 m. Hány méter hosszú a pálya egy oldala? (100 / 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "6d2bbbaf-2fa9-44f8-a810-f658f7f8dfc0", "text": "Ha a téglalap kerülete 30 cm, és egyik oldala 5 cm, mekkora a másik oldal? (15 - 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "ad6cb2b3-e807-4b33-b0ce-2af9c6705b41", "text": "A sokszögek kerületét mindig hosszúság-mértékegységben (m, cm, mm) adjuk meg.", "type": "true-false", "options": [{"id": "335162a4-540a-4951-bcd8-8f92b9cde619", "text": "Igaz", "isCorrect": true}, {"id": "13c81559-b167-403e-a179-e5b39f5d16f7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "da9c6d9f-c6ca-4544-9754-13d468c10015", "text": "Mennyi a 10 cm oldalú szabályos hatszög kerülete?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "efbaeefc-3b72-4bc2-8025-d6619006d768", "text": "A kerületszámításos feladatoknál az oldalaknak azonos mértékegységben kell lenniük.", "type": "true-false", "options": [{"id": "67cfff43-be7b-4700-bf97-60942eeb3982", "text": "Igaz", "isCorrect": true}, {"id": "4294b251-6a93-47dc-be78-3c8406d407af", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ade13198-99cf-49e0-a0c0-121bd2104575', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$102. óra: A terület és a térfogat mérése$q$, $q$A terület és térfogat mértékegységei, lefedés, egységkockák, átváltások.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "ad927645-6610-4515-8bbf-f2f16cda87aa", "text": "Mi a terület alapvető mértékegysége az SI-ben?", "type": "multiple-choice", "options": [{"id": "1fcb7bed-271d-4eb8-8fb1-7208b17f00e5", "text": "Négyzetméter (m²)", "isCorrect": true}, {"id": "de347198-90a8-4431-9b4b-93af0901d349", "text": "Méter (m)", "isCorrect": false}, {"id": "ebaf0698-7300-420b-a710-abe0a87e215c", "text": "Köbméter (m³)", "isCorrect": false}, {"id": "cdf5f66e-26f5-469f-ac47-c07643a85a9f", "text": "Liter (l)", "isCorrect": false}], "timeLimit": 15}, {"id": "040b86fa-c4e6-4798-9d97-c3b0c08b0db5", "text": "Hány cm² 1 dm²? (10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "87e60b9a-203a-41fa-9f35-0748d95bd45b", "text": "Hány dm² 1 m²? (10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "1190da97-5fc2-47ee-aca5-32b66ecec25e", "text": "Hány dm³ 1 m³? (10 * 10 * 10)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "3d118bb5-3434-4356-bde7-a931f0696510", "text": "1 liter űrtartalom pontosan 1 köbdeciméternek (1 dm³) felel meg.", "type": "true-false", "options": [{"id": "a261d4c0-717b-4ead-977a-1b96c2e2cde2", "text": "Igaz", "isCorrect": true}, {"id": "994e9e8f-ace5-46b3-a1bc-e22a86e20fa1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1baec99f-0e78-46e3-91d2-2188e9b33940", "text": "Hány cm³ 1 dm³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "4d755b78-9f66-460d-92df-bb9d67f9bf22", "text": "A terület mértékegységei között a szomszédos váltószám 100 (területnél 10²).", "type": "true-false", "options": [{"id": "19c19522-4c81-485f-a6f7-563a99d97831", "text": "Igaz", "isCorrect": true}, {"id": "c2b9ea29-fd75-407a-b724-1fa88a4bae71", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ec59455e-03ce-47c1-ba87-eabe7e746a50', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$103. óra: Gyakorlóóra. A terület és a térfogat mérése$q$, $q$Terület- és térfogat-mértékegységek gyakorlása digitális feladatlapokon.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "3174499e-9381-49a3-b47e-2ebc9728b25a", "text": "Hány mm² 1 cm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "6a4d089e-d21a-4d7c-be39-b9ef0845691c", "text": "Hány cm³ 2 liter? (2 dm³ = 2000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2000"}, {"id": "30b6d42c-e0a7-484b-b7f1-95ccad15d4fb", "text": "Hány m² 500 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "61133047-6078-4e2a-ac9b-b8e3a2abb7d7", "text": "Hány litere felel meg 3,5 dm³ víznek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3.5"}, {"id": "f82ca1b4-cdc7-4549-b0f9-b8114658a567", "text": "A térfogat mértékegységei között a szomszédos váltószám 1000 (10³).", "type": "true-false", "options": [{"id": "67157018-78a0-4acc-a110-5aed342d07f9", "text": "Igaz", "isCorrect": true}, {"id": "09a9814d-e491-48c1-9955-6a8166e164c1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "24b5cde7-7e71-4462-9aaf-b8e05964d26e", "text": "Hány dl 1 liter?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10"}, {"id": "be2a4776-8917-4141-8c23-a1a6a2691146", "text": "Hány ml 1 dm³ (1 liter)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('49c2e125-ba56-4deb-820c-88d86b0b79dc', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$104. óra: A sokszögek területe$q$, $q$Négyzet, téglalap és derékszögű háromszög területe (T).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "894fdd47-99eb-4cc1-95dd-4f44edb29a69", "text": "Mi a téglalap területének képlete (a és b oldallal)?", "type": "multiple-choice", "options": [{"id": "8a283f7e-69fd-404d-ba58-3bcf46017a95", "text": "T = a * b", "isCorrect": true}, {"id": "b75daf73-4225-4e4c-a0f3-3001726cce8f", "text": "T = 2 * (a + b)", "isCorrect": false}, {"id": "2cb13cfc-ed8a-4a6b-8dab-f19f55f6a2e7", "text": "T = a + b", "isCorrect": false}, {"id": "ea3497c1-1b8a-4e84-a72f-aff357c3ae56", "text": "T = a * a * a", "isCorrect": false}], "timeLimit": 15}, {"id": "6d2ee650-420c-41cb-90c9-2069cd05f01e", "text": "Mi a négyzet területének képlete ('a' oldallal)?", "type": "multiple-choice", "options": [{"id": "24095d8f-4a2f-4eb4-b994-3eb4d8c1f1ee", "text": "T = a * a (a²)", "isCorrect": true}, {"id": "b45c1b4b-f532-474f-91e1-6d857506bf68", "text": "T = 4 * a", "isCorrect": false}, {"id": "7bc325a3-134f-4a55-bb82-acf373e81efd", "text": "T = 2 * a", "isCorrect": false}, {"id": "6f903c1d-4f02-4443-80d7-eb1a68a87332", "text": "T = a * 10", "isCorrect": false}], "timeLimit": 15}, {"id": "b9b8a3f4-98ab-49cf-a855-76b07c4be237", "text": "Mennyi a 6 cm és 8 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "48"}, {"id": "15828d14-9d2a-489f-86a4-51b791085a0c", "text": "Mennyi a 5 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "0805a731-03a1-43f2-a262-edbc78c02f6f", "text": "Mi a derékszögű háromszög területének képlete (a és b befogókkal)?", "type": "multiple-choice", "options": [{"id": "15ecb4c1-43f2-4aef-ba25-1fce098796c9", "text": "T = (a * b) / 2", "isCorrect": true}, {"id": "399a911e-f047-4dda-82d2-34f1ff7a784f", "text": "T = a * b", "isCorrect": false}, {"id": "094a221e-59a4-4a48-ae23-5a8ef8a630bd", "text": "T = a + b", "isCorrect": false}, {"id": "df38b89e-3b9a-4859-90e0-d5da7f68a8dc", "text": "T = 2 * a * b", "isCorrect": false}], "timeLimit": 15}, {"id": "f6a75e87-c2ef-4415-a58d-50c7c282792e", "text": "Mennyi a 6 cm és 8 cm befogójú derékszögű háromszög területe? ((6*8)/2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "daaf529e-106b-459e-8543-9290fb2b5163", "text": "A derékszögű háromszög területe a két befogójú téglalap területének fele.", "type": "true-false", "options": [{"id": "164157cf-fd42-418e-8130-3115e889020b", "text": "Igaz", "isCorrect": true}, {"id": "1ef8a3d3-16ec-49f1-872c-e0446d5dcffa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('4c350b2b-e58c-4aa3-8c06-5612926e6846', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$105. óra: Feladatmegoldás$q$, $q$Kerület- és területszámítási feladatok, lakóház és szobapadló tervezése.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "c2089940-f85e-4506-ac12-c79e96a641d4", "text": "Egy 5 m hosszú és 4 m széles szobába szőnyeget fektetünk. Hány m² a szoba területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "20"}, {"id": "2a52e0d2-3475-47a5-919d-fd56ac5c4dbb", "text": "Ha a parketta ára 5000 Ft/m², mennyibe kerül a 20 m²-es szoba parkettázása?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100000"}, {"id": "2efe589c-7cb0-4083-b92b-4de83c718b0a", "text": "Hány méter szegélylécre van szükség a 5m x 4m-es szobához (kerület)? (2*(5+4))", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "18"}, {"id": "229ecc0b-d608-42d4-8422-6e6f6332bec7", "text": "Egy négyzet alakú szoba területe 36 m². Hány méter hosszú a szoba egy oldala?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "05d37383-3e77-4c0e-9dcb-72a71a9bcf96", "text": "A terület számításához a méreteket azonos mértékegységre kell hozni a szorzás előtt.", "type": "true-false", "options": [{"id": "107a1473-e07c-4e2b-8870-7da4b6b08591", "text": "Igaz", "isCorrect": true}, {"id": "26f9efd8-b11c-4c88-9c2c-8ab26d43fef7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ba9bf4ed-744e-47df-a347-85059f8b666c", "text": "Mennyi a 10 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "30866b24-8130-4f7e-b80f-b0c77ab023cc", "text": "A lakástervezésben a m² alapvető fontosságú.", "type": "true-false", "options": [{"id": "6f55c030-628d-494e-a0d3-c5644981183b", "text": "Igaz", "isCorrect": true}, {"id": "69209311-b9b5-4594-ad91-5a413e8e1fc5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('48e420d3-8f87-4f5b-8234-da1b5ee89aa0', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$106. óra: Alakzatok a térben$q$, $q$Testek elnevezései (kocka, téglatest, hasáb, piramis), él, lap, csúcs, nézetek (elölnézet, felülnézet, oldalnézet).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "67c73cf5-e942-405d-8945-9b5229b32224", "text": "Hány lapja van a téglatestnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "4756bc10-849a-4a46-ae33-82c26cea1088", "text": "Hány csúcsa van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "0c5211af-07ae-4698-9416-fab2c8f0fc40", "text": "Hány éle van a téglatestnek (és a kockának)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}, {"id": "cfa19e80-d613-4fbb-8ff0-a670c86e7a6b", "text": "A kocka minden lapja egyenlő négyzet.", "type": "true-false", "options": [{"id": "4e590623-f6ae-425c-9a67-10810279eaa9", "text": "Igaz", "isCorrect": true}, {"id": "b7776058-3936-45ea-9182-661ec49e0ca7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "6d7efff2-7ff6-4aa8-bff3-53d74182b628", "text": "Milyen alakúak a téglatest lapjai?", "type": "multiple-choice", "options": [{"id": "b5103e6b-71bc-4306-b3d6-9f73cfd40315", "text": "Téglalapok (melyek között négyzet is lehet)", "isCorrect": true}, {"id": "c508c0f1-38eb-4229-822f-9bc93850720e", "text": "Háromszögek", "isCorrect": false}, {"id": "965039b7-9ccf-45c0-b474-134f90554002", "text": "Körök", "isCorrect": false}, {"id": "de15daca-fdcb-46ef-b0ad-9442f6065c3b", "text": "Ötszögek", "isCorrect": false}], "timeLimit": 15}, {"id": "7c8a121b-8c5d-4fd6-a098-03fc3ee9c4da", "text": "A testek felülről, elölről és oldalról készített 2D vetületei a vetületi képek.", "type": "true-false", "options": [{"id": "6b45e4d3-cdbc-407f-b57a-dcfe53cbe52e", "text": "Igaz", "isCorrect": true}, {"id": "d268f2a7-a761-459c-b472-03f227bcc7e2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1fa0df6c-5453-44e9-8f6c-3740459f360f", "text": "Hány lapja van a négyszög alapú gúlának (piramisnak)? (1 alap + 4 oldal)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('12de4ca7-9e0b-494f-b542-0d2654844f21', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$107. óra: Testek felszíne$q$, $q$Kocka és téglatest felszínének kiszámítása (A vagy F).$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "fb023168-7097-43a0-812b-59aa0d4abc11", "text": "Mi a kocka felszínének képlete ('a' éllel)?", "type": "multiple-choice", "options": [{"id": "a248ab4d-6921-4ef8-84bc-d97ad5ca70bf", "text": "F = 6 * a * a (6 * a²)", "isCorrect": true}, {"id": "cdd50434-82f4-42ff-a631-43d42dcd831c", "text": "F = a * a * a", "isCorrect": false}, {"id": "2ea0f7a1-efe1-459e-8f14-6dd3fb2afa3a", "text": "F = 12 * a", "isCorrect": false}, {"id": "a8d2f10f-c7c3-4bab-8b9e-65b35404930b", "text": "F = 4 * a²", "isCorrect": false}], "timeLimit": 15}, {"id": "2795d107-47e0-4bb9-ad3f-d8ab11ff1673", "text": "Mi a téglatest felszínének képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "fdb932f7-bde1-44de-bea1-dcc29904d052", "text": "F = 2 * (a*b + a*c + b*c)", "isCorrect": true}, {"id": "e55a006e-83ab-4424-bbcb-edd3d5f05ac1", "text": "F = a * b * c", "isCorrect": false}, {"id": "74a1eadf-4267-48d7-8347-d7d2f5723998", "text": "F = 4 * (a + b + c)", "isCorrect": false}, {"id": "c7eb0123-e204-4703-8233-80cfc73f1c29", "text": "F = a*b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "9c5d7c13-2758-469b-b525-a3aaf3488e4f", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "023688e3-9b76-40b7-ae2a-cf10410261c0", "text": "Mennyi a 2 cm, 3 cm, 4 cm élű téglatest felszíne? (2*(2*3 + 2*4 + 3*4) = 2*(6+8+12) = 2*26)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "52"}, {"id": "f574f171-7d65-4f85-a8cb-78f3dbbf9915", "text": "A felszín a testet határoló lapok területeinek összege.", "type": "true-false", "options": [{"id": "8a3294d0-784b-4978-bee6-282383fcdacc", "text": "Igaz", "isCorrect": true}, {"id": "b97a9f1e-6bcb-4eb9-8aa6-0020fb6e4508", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b880856c-d924-4be6-b7a0-2128cacccfd1", "text": "A felszínt mindig terület-mértékegységben (cm², m²) adjuk meg.", "type": "true-false", "options": [{"id": "35c3db23-f420-4644-af38-f409253c7bc8", "text": "Igaz", "isCorrect": true}, {"id": "0bc0f39a-72e3-43ea-ac8e-1af43bf3c514", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a0effc2b-acd8-4074-90e2-93b582f6b578", "text": "Mennyi a 10 cm élű kocka felszíne? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "600"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('5579e4f2-6d39-46ab-93c6-b98d6c2312e8', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$108. óra: Gyakorlóóra$q$, $q$Felszínszámítás gyakorlása hálók megrajzolásával és szerkesztőprogrammal.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "2787204a-ef65-4633-a6da-41dbb93cb1fc", "text": "Hány négyzetből áll a kocka hálója?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "df5ff7a7-389d-4ea5-96f2-69be2e73e766", "text": "Mennyi a 4 cm élű kocka felszíne? (6 * 16)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "acd8d5f9-87be-4bea-b6b6-4cab32f93f16", "text": "Mennyi a 1 m, 2 m, 3 m élű téglatest felszíne? (2*(2+3+6) = 2*11)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "01b17422-45e4-425d-99b8-de65e04183f6", "text": "A test hálójának területe megegyezik a test felszínével.", "type": "true-false", "options": [{"id": "6819cc14-a1bd-436d-86f4-136dbab736be", "text": "Igaz", "isCorrect": true}, {"id": "dbef6f4f-a7ce-40c0-ad53-8f623b2d1c08", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "bead98ed-9e67-4671-a806-50af6f0e4edb", "text": "Mennyi a 5 cm élű kocka felszíne? (6 * 25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "5adb224c-edb1-41b5-ba23-2017d2da0f76", "text": "Dinamikus szerkesztőprogrammal a testek hálója kiteríthető és összehajtható.", "type": "true-false", "options": [{"id": "49d179cb-0832-4ed3-95ab-9310e8229c76", "text": "Igaz", "isCorrect": true}, {"id": "0c6a3931-5109-4f96-879a-a148936e0937", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5c27d399-deea-44b4-a573-a0292f3b9cd5", "text": "A téglatest szemközti lapjai egyenlő területűek.", "type": "true-false", "options": [{"id": "69894e0e-fa3f-43bf-903f-34e609b03fd1", "text": "Igaz", "isCorrect": true}, {"id": "71f87012-462a-436d-85b1-5b41ebc08ce0", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('3038e908-cb88-44df-9972-310cb55be0a8', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$109. óra: Felszínszámítással kapcsolatos gyakorlati feladatok$q$, $q$Dobozok lefestése, csomagolópapír szükséglet kiszámítása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "4c0ecd73-ece5-4795-bb71-73864b05fbe2", "text": "Egy 10 cm x 20 cm x 30 cm-es téglatest dobozt befestünk. Hány cm² felületet kell lefesteni? (2*(200+300+600) = 2*1100)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2200"}, {"id": "6c03e767-8bc6-4d44-bb89-550ca6e13aa1", "text": "Hány cm² csomagolópapír kell egy 5 cm élű kocka alakú ajándék becsomagolásához (ráhagyás nélkül)? (6 * 25)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "1aa59f44-6056-4d5f-876a-3ae60b7ab078", "text": "Ha a festékből 1 m²-re 200 g kell, hány gramm festék kell 5 m² felszínre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}, {"id": "137d5953-e284-4d10-afd0-0ecc4e1d5552", "text": "Csomagoláskor a veszteség és az átfedés miatt érdemes a kiszámított felszínnél kb. 10-20%-kal több papírral számolni.", "type": "true-false", "options": [{"id": "a8394134-0d44-4f62-a1e3-e358f3a87887", "text": "Igaz", "isCorrect": true}, {"id": "5219cdd2-e5f7-4516-943a-c5797f090bd8", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "000d8efd-ace2-4966-90e0-2e4217fa4e34", "text": "Mennyi a 2 cm élű kocka felszíne? (6 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "3ebccafb-ea62-43eb-aa61-226aa2749eba", "text": "A dobozok tervezésénél az anyagszükségletet a felszín határozza meg.", "type": "true-false", "options": [{"id": "a8056178-e84e-4263-95c2-a8eb9944782c", "text": "Igaz", "isCorrect": true}, {"id": "5bda26bd-df38-4457-8a00-f8f70a31df6f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "21ab0129-69c8-4431-b7b5-52ba5b15f81e", "text": "Mennyi a 1 cm élű kocka felszíne?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('c4f40f43-e8ae-4fb5-a90e-bc04cb002da4', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$110. óra: Testek térfogata$q$, $q$Téglatest és kocka térfogatának (V) kiszámítása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Kerület, terület, felszín, térfogat$q$, $q$[{"id": "80c217e1-0016-4952-bd71-e659011ea118", "text": "Mi a kocka térfogatának képlete ('a' éllel)?", "type": "multiple-choice", "options": [{"id": "782c5e82-f20c-4709-aa93-cfd61a062449", "text": "V = a * a * a (a³)", "isCorrect": true}, {"id": "7ec61c40-1323-41f6-bec2-3f1dc24a0a68", "text": "V = 6 * a²", "isCorrect": false}, {"id": "87a7f868-c98c-4f76-96c1-1b0496d707db", "text": "V = 12 * a", "isCorrect": false}, {"id": "76d4a04c-556a-4c86-a384-e0bde459760e", "text": "V = a + a + a", "isCorrect": false}], "timeLimit": 15}, {"id": "221b47e4-49ed-47f0-93e9-86a54d5e2e28", "text": "Mi a téglatest térfogatának képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "4ae8a927-b08c-48bc-b395-f5bb144abcc3", "text": "V = a * b * c", "isCorrect": true}, {"id": "d730eff3-dc38-4ba0-9a73-3acee474a265", "text": "V = 2 * (a+b+c)", "isCorrect": false}, {"id": "cb96f859-8774-4bfa-8c0c-c3d96f01a242", "text": "V = a * b", "isCorrect": false}, {"id": "b770c21f-b966-473d-b45b-3ff71854697a", "text": "V = a + b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "080bf838-bc09-43ac-bfa1-ff23af00bdee", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "5c64c9c3-7259-4169-a985-726ec543e9a4", "text": "Mennyi a 2 cm, 4 cm, 5 cm élű téglatest térfogata? (2 * 4 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "5dc3f758-b8ad-4482-9084-0f1bdc97e566", "text": "A térfogatot mindig köbmértékegységben (cm³, m³, dm³) vagy űrmértékben (liter, dl) adjuk meg.", "type": "true-false", "options": [{"id": "68a3e449-d80f-482b-a104-fb829a64dda6", "text": "Igaz", "isCorrect": true}, {"id": "51a26f14-da40-4eee-9bb1-5705ff47fc25", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5e3360b7-9b56-457c-88cd-ceb32390af03", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "7ce2d1d7-8786-4c3d-928f-f5b65fb8a642", "text": "Mennyi a 10 cm élű kocka térfogata cm³-ben? (1000 cm³ = 1 liter)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;